# read sales.csv
with open('sales.csv', 'r', newline='') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
print('Columns:', reader.fieldnames)
# extract price column, assuming numeric strings
prices = []
for row in rows:
    val = row.get('price') or row.get('Price') or row.get('PRICE')
    if val is not None:
        try:
            prices.append(float(val))
        except ValueError:
            pass
print('Number of price entries:', len(prices))
if prices:
    avg = sum(prices)/len(prices)
    print('Average price:', avg)
else:
    print('No price data')
