east_rev = {}
with open('sales.csv', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['region'].lower() == 'east':
            quarter = row['quarter']
            units = float(row['units'])
            price = float(row['price'])
            rev = units * price
            east_rev[quarter] = east_rev.get(quarter, 0) + rev

for q in sorted(east_rev):
    print(f"East {q} revenue: {east_rev[q]:.2f}")"
